 init=method(tree,'__init__');defaults=dict(zip([x.arg for x in init.args.args][-len(init.args.defaults):],init.args.defaults))
 for k,v in cfg.items():assert ast.literal_eval(defaults[k])==v or list(ast.literal_eval(defaults[k]))==v
 for node in ast.walk(tree):
  if isinstance(node,ast.Import):assert all(x.name.split('.')[0] in {'torch','unirank'} for x in node.names)
  if isinstance(node,ast.ImportFrom):assert node.module.split('.')[0] in {'torch','unirank'}
  if isinstance(node,ast.Call) and isinstance(node.func,ast.Name):assert node.func.id not in {'open','eval','exec','__import__'}
 for n in model(tree).body:
  if isinstance(n,ast.FunctionDef) and n.name not in ('__init__','_joint_coefficients'):
   assert norm(n)==norm(method(ref,n.name)),n.name
# At fixed width, constructors, parameters, RNG and all other methods are unchanged.
assert norm(method(ref,'__init__'))==norm(method(active,'__init__'))
assert norm(method(full10,'__init__'))==norm(method(active10,'__init__'))
for t in [full10,active10]:
 init=copy.deepcopy(method(t,'__init__'))
 for arg,default in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
  if arg.arg=='residual_hidden':default.value=12
 assert norm(init)==norm(method(ref,'__init__'))
# Verify every retained live assignment is an exact AST copy, in the same order.
old=method(ref,'_joint_coefficients');new=method(active,'_joint_coefficients')
assigns={n.targets[0].id:n for n in old.body if isinstance(n,ast.Assign) and isinstance(n.targets[0],ast.Name)}
live_names=['position_norm2','match_norm2','available','available_norm']
new_stmts=new.body[1:]
assert [n.targets[0].id for n in new_stmts[:-1]]==live_names
for name,n in zip(live_names,new_stmts[:-1]):assert norm(n)==norm(assigns[name]),name
assert isinstance(new_stmts[-1],ast.Return) and new_stmts[-1].value.id=='available_norm'
# Resolve each retained assignment's data dependencies: no discarded variable is live.
known={'affinity','position','valid'}
for name,n in zip(live_names,new_stmts[:-1]):
 loaded={x.id for x in ast.walk(n.value) if isinstance(x,ast.Name) and isinstance(x.ctx,ast.Load)}
 assert loaded<=known,(name,loaded-known)
 known.add(name)
assert norm(method(active,'_joint_coefficients'))==norm(method(active10,'_joint_coefficients'))
for f in files:
 source=(root/f).read_text();compile(source,str(root/f),'exec')
 print(f,hashlib.sha256(source.encode()).hexdigest())
